  entry("agheel", "summonwater", "Limgrave \xB7 Kh\xE1m ph\xE1", "H\u1EA1 Tibia Mariner \u1EDF Summonwater", "Boss", 1045390800, "Summonwater Village, \u0111\xF4ng b\u1EAFc Limgrave", ["\u0110\u1EBFn l\xE0ng ng\u1EADp n\u01B0\u1EDBc \u1EDF \u0111\xF4ng b\u1EAFc Limgrave; g\u1EB7p D g\u1EA7n \u0111\u01B0\u1EDDng v\xE0o n\u1EBFu h\u1EAFn c\xF2n \u1EDF \u0111\xF3.", "H\u1EA1 Tibia Mariner, l\u1EA5y Deathroot.", "Sau \u0111\xF3 n\xF3i v\u1EDBi D \u0111\u1EC3 m\u1EDF tuy\u1EBFn Gurranq v\xE0 Bestial Sanctum."]),
  entry("summonwater", "night-cavalry-limgrave", "Limgrave \xB7 Kh\xE1m ph\xE1", "H\u1EA1 Night\u2019s Cavalry t\u1EA1i Limgrave", "Boss \u0111\xEAm", 1043370800, "C\u1EA7u \u0111\u01B0\u1EDDng ch\xEDnh g\u1EA7n Agheel Lake North, ch\u1EC9 ban \u0111\xEAm", ["Ngh\u1EC9 t\u1EA1i \xE2n \u0111i\u1EC3n t\u1EDBi Nightfall.", "Ra c\xE2y c\u1EA7u tr\xEAn \u0111\u01B0\u1EDDng ch\xEDnh ph\xEDa \u0111\xF4ng Gatefront, t\xECm k\u1EF5 s\u0129 \xE1o \u0111en.", "\u0110\xE1nh ng\xE3 ng\u1EF1a r\u1ED3i h\u1EA1 k\u1EF5 s\u0129; ki\u1EC3m tra Ash of War nh\u1EADn \u0111\u01B0\u1EE3c."]),
  entry("irina", "pilgrimage-tear", "Weeping Peninsula", "L\u1EA5y Sacred Tear \u1EDF Church of Pilgrimage", "V\u1EADt ph\u1EA9m", null, "Church of Pilgrimage, ph\xEDa b\u1EAFc Weeping Peninsula", ["T\u1EEB Bridge of Sacrifice \u0111i l\xEAn v\xF9ng \u0111\u1ED3i ph\xEDa b\u1EAFc b\xE1n \u0111\u1EA3o.", "V\xE0o Church of Pilgrimage, ch\u1EA1m \xE2n \u0111i\u1EC3n v\xE0 nh\u1EB7t Sacred Tear d\u01B0\u1EDBi t\u01B0\u1EE3ng."]),
  entry("pilgrimage-tear", "weep-erdtree", "Weeping Peninsula", "H\u1EA1 Erdtree Avatar t\u1EA1i Minor Erdtree", "Boss", 1043330800, "Minor Erdtree, gi\u1EEFa b\xE1n \u0111\u1EA3o", ["\u0110i t\u1EDBi Minor Erdtree \u1EDF trung t\xE2m Weeping Peninsula.", "Tr\xE1nh c\xFA \u0111\u1EADp t\u1EA1o lu\u1ED3ng s\xE1ng r\u1ED3i ph\u1EA3n c\xF4ng sau m\u1ED7i chu\u1ED7i.", "Nh\u1EB7t Crystal Tears r\u01A1i ra v\xE0 th\u1EED ph\u1ED1i v\xE0o Wondrous Physick."]),
  entry("weeping-map", "oridys", "Weeping Peninsula", "M\u1EDF Oridys\u2019s Rise, l\u1EA5y Memory Stone", "V\u1EADt ph\u1EA9m", null, "Oridys\u2019s Rise, b\u1EDD \u0111\xF4ng b\xE1n \u0111\u1EA3o", ["\u0110\u1EBFn th\xE1p \u1EDF ph\xEDa \u0111\xF4ng Weeping Peninsula.", "Gi\u1EA3i c\xE2u \u0111\u1ED1 ba linh v\u1EADt r\xF9a quanh th\xE1p.", "L\xEAn \u0111\u1EC9nh th\xE1p m\u1EDF r\u01B0\u01A1ng l\u1EA5y Memory Stone \u0111\u1EC3 t\u0103ng \xF4 ph\xE9p."]),
  entry("oridys", "weep-night-cavalry", "Weeping Peninsula", "H\u1EA1 Night\u2019s Cavalry g\u1EA7n Castle Morne", "Boss \u0111\xEAm", 1044320850, "\u0110\u01B0\u1EDDng g\u1EA7n Castle Morne Rampart, ban \u0111\xEAm", ["Ngh\u1EC9 t\u1EA1i Castle Morne Rampart t\u1EDBi \u0111\xEAm.", "\u0110i d\u1ECDc \u0111\u01B0\u1EDDng ch\xEDnh g\u1EA7n \xE2n \u0111i\u1EC3n \u0111\u1EC3 t\xECm Night\u2019s Cavalry.", "H\u1EA1 k\u1EF5 s\u0129 \u0111\u1EC3 l\u1EA5y Nightrider Flail v\xE0 Ash of War: Barricade Shield."]),
  entry("weep-night-cavalry", "morne-claymore", "Weeping Peninsula", "L\u1EA5y Claymore trong Castle Morne", "V\u0169 kh\xED", null, "Castle Morne, ph\xF2ng c\u1EA1nh s\xE2n x\xE1c ng\u01B0\u1EDDi", ["\u0110i thang m\xE1y v\xE0o Castle Morne, qua s\xE2n n\u01A1i c\xE1c Misbegotten \u0111ang \u0111\xE1nh nhau.", "Leo l\xEAn b\u1EDD t\u01B0\u1EDDng th\u1EA5p r\u1ED3i v\xE0o c\u0103n ph\xF2ng c\u1EA1nh s\xE2n.", "M\u1EDF r\u01B0\u01A1ng l\u1EA5y Claymore tr\u01B0\u1EDBc khi ti\u1EBFn s\xE2u xu\u1ED1ng b\u1EDD bi\u1EC3n."]),
  entry("margit", "stormveil-nepheli", "Stormveil Castle", "G\u1EB7p Nepheli Loux tr\u01B0\u1EDBc Godrick", "Quest", null, "Stormveil Castle, ph\xF2ng nh\u1ECF g\u1EA7n Secluded Cell", ["T\u1EEB l\u1ED1i trong Stormveil, t\xECm ph\xF2ng Nepheli tr\u01B0\u1EDBc khi v\xE0o s\xE2n Godrick.", "N\xF3i h\u1EBFt h\u1ED9i tho\u1EA1i; c\xF3 th\u1EC3 tri\u1EC7u h\u1ED3i c\xF4 \u1EDF tr\u1EADn Godrick.", "Sau boss, ki\u1EC3m tra c\xF4 t\u1EA1i Roundtable Hold \u0111\u1EC3 theo d\xF5i quest."]),
  entry("stormveil-nepheli", "stormveil-grafted", "Stormveil Castle", "D\u1ECDn Grafted Scion v\xE0 nh\u1EB7t \u0111\u1ED3 quanh Dining Room", "Elite", null, "Stormveil Castle, ph\xF2ng \u0103n ph\xEDa trong", ["M\u1EDF \u0111\u01B0\u1EDDng t\u1EDBi ph\xF2ng l\u1EDBn c\xF3 Grafted Scion.", "D\xF9ng c\u1EEDa v\xE0 kho\u1EA3ng c\xE1ch \u0111\u1EC3 x\u1EED l\xFD elite; r\xE0 c\xE1c ph\xF2ng c\u1EA1nh \u0111\xF3 \u0111\u1EC3 l\u1EA5y v\u0169 kh\xED v\xE0 v\u1EADt ph\u1EA9m.", "\u0110\xE1nh d\u1EA5u th\u1EE7 c\xF4ng v\xEC b\u1EA3n demo ch\u01B0a g\u1EAFn c\u1EDD h\u1EA1 elite."]),
  entry("godrick", "stormveil-loot", "Stormveil Castle", "R\xE0 Stormveil tr\u01B0\u1EDBc khi r\u1EDDi l\xE2u \u0111\xE0i", "V\u1EADt ph\u1EA9m", null, "Stormveil Castle, s\xE2n trong, m\xE1i nh\xE0 v\xE0 t\u1EA7ng h\u1EA7m", ["T\u1EEB Liftside Chamber, ki\u1EC3m tra c\xE1c l\u1ED1i s\xE2n trong v\xE0 m\xE1i nh\xE0.", "Nh\u1EB7t Golden Seed t\u1EA1i c\xE2y non, t\xECm Chrysalids\u2019 Memento cho Roderika v\xE0 Prayerbook \u1EDF c\xE1c nh\xE1nh ph\u1EE5.", "Ki\u1EC3m tra ph\xEDa d\u01B0\u1EDBi l\xE2u \u0111\xE0i \u0111\u1EC3 xem d\u1EA5u v\u1EBFt Godwyn, r\u1ED3i n\xF3i l\u1EA1i v\u1EDBi Rogier n\u1EBFu theo quest."]),
  entry("liurnia", "irith-thops", "Liurnia", "G\u1EB7p Thops t\u1EA1i Church of Irith", "Quest", null, "Church of Irith, ngay sau l\u1ED1i ra Stormveil", ["T\u1EEB Lake-Facing Cliffs \u0111i v\u1EC1 ph\xEDa nam t\u1EDBi Church of Irith.", "N\xF3i v\u1EDBi Thops v\xE0 nh\u1EB7t Sacred Tear d\u01B0\u1EDBi t\u01B0\u1EE3ng.", "Ghi nh\u1EDB r\u1EB1ng Academy Glintstone Key th\u1EE9 hai d\xF9ng cho quest c\u1EE7a Thops."]),
  entry("irith-thops", "academy-key", "Liurnia", "L\u1EA5y Academy Glintstone Key \u0111\u1EA7u ti\xEAn", "V\u1EADt ph\u1EA9m", null, "\u0110\u1EA3o \u0111\xE1 ph\xEDa t\xE2y Raya Lucaria, sau Glintstone Dragon Smarag", ["T\u1EEB khu h\u1ED3, \u0111i v\u1EC1 ph\xEDa t\xE2y h\u1ECDc vi\u1EC7n t\u1EDBi n\u01A1i Smarag canh x\xE1c h\u1ECDc gi\u1EA3.", "C\xF3 th\u1EC3 c\u01B0\u1EE1i Torrent l\xE1ch qua r\u1ED3ng \u0111\u1EC3 l\u1EA5y ch\xECa kh\xF3a tr\xEAn x\xE1c.", "D\xF9ng ch\xECa kh\xF3a \u1EDF c\u1ED5ng nam Raya Lucaria Academy."]),
  entry("academy-key", "lucaria-crystal", "Liurnia", "L\u1EA5y Smithing-Stone Miner\u2019s Bell Bearing [1]", "Boss", 32020800, "Raya Lucaria Crystal Tunnel, b\u1EDD \u0111\xF4ng Liurnia", ["V\xE0o h\u1EA7m \u1EDF ph\xEDa \u0111\xF4ng b\u1EAFc h\u1ED3; nh\u1EB7t Smithing Stones tr\xEAn \u0111\u01B0\u1EDDng.", "H\u1EA1 Crystalian \u1EDF cu\u1ED1i h\u1EA7m.", "\u0110\u01B0a Bell Bearing [1] cho Twin Maiden Husks \u0111\u1EC3 mua \u0111\xE1 n\xE2ng c\u1EA5p c\u1EA5p th\u1EA5p."]),
  entry("academy-wolf", "radagon-icon", "Liurnia", "L\u1EA5y Radagon Icon trong h\u1ECDc vi\u1EC7n", "Talisman huy\u1EC1n tho\u1EA1i", null, "Raya Lucaria Academy, t\u1EA7ng tr\xEAn Debate Parlor", ["T\u1EEB \xE2n \u0111i\u1EC3n Debate Parlor, ra s\xE2n r\u1ED3i \u0111i sang ph\u1EA3i t\u1EDBi thang c\u1EA1nh t\u01B0\u1EDDng.", "\u0110i tr\xEAn h\xE0nh lang t\u1EA7ng hai v\xE0 m\u1EDF r\u01B0\u01A1ng ch\u1EE9a Radagon Icon.", "\u0110\xE1nh d\u1EA5u th\u1EE7 c\xF4ng; \u0111\xE2y l\xE0 m\u1ED9t ph\u1EA7n b\u1ED9 Legendary Talismans cho th\xE0nh t\u1EF1u."]),
  entry("rennala", "albinauric-medallion", "Liurnia", "L\u1EA5y n\u1EEDa Haligtree Medallion \u1EDF Village of the Albinaurics", "V\u1EADt ph\u1EA9m", null, "Village of the Albinaurics, t\xE2y nam Liurnia", ["T\u1EEB h\u1ED3 ph\xEDa t\xE2y nam, l\xEAn \u0111\u01B0\u1EDDng m\xF2n d\u01B0\u1EDBi v\xE1ch \u0111\xE1 t\u1EDBi l\xE0ng.", "T\xECm chi\u1EBFc b\xECnh ng\u1EE5y trang v\xE0 \u0111\xE1nh m\u1ED9t l\u1EA7n \u0111\u1EC3 l\u1ED9 Albus.", "N\xF3i chuy\u1EC7n v\u1EDBi Albus \u0111\u1EC3 nh\u1EADn Haligtree Secret Medallion (Right)."]),
  entry("albinauric-medallion", "latenna", "Liurnia", "G\u1EB7p Latenna v\xE0 nh\u1EADn Spirit Ash", "Quest", null, "Slumbering Wolf\u2019s Shack, sau Lakeside Crystal Cave", ["V\xE0o Lakeside Crystal Cave \u1EDF b\u1EDD t\xE2y nam h\u1ED3, h\u1EA1 boss \u1EDF cu\u1ED1i.", "Ra c\u1EEDa sau t\u1EDBi Slumbering Wolf\u2019s Shack, n\xF3i v\u1EDBi Latenna khi \u0111\xE3 c\xF3 n\u1EEDa medallion c\u1EE7a Albus.", "Nh\u1EADn Latenna the Albinauric Spirit Ash v\xE0 gi\u1EEF quest cho Consecrated Snowfield."]),
  entry("latenna", "caria-loretta", "Liurnia", "H\u1EA1 Royal Knight Loretta \u1EDF Caria Manor", "Boss", 1035500800, "Caria Manor, t\xE2y b\u1EAFc Liurnia", ["\u0110i qua Caria Manor, n\xE9 b\xE0n tay kh\u1ED5ng l\u1ED3 v\xE0 m\u1EDF c\xE1c \xE2n \u0111i\u1EC3n.", "H\u1EA1 Royal Knight Loretta \u1EDF s\xE2n cu\u1ED1i.", "C\u1ED5ng sau m\u1EDF khu Three Sisters v\xE0 Ranni\u2019s Rise."]),
  entry("radahn", "mimic-tear", "Nokron & Ranni", "H\u1EA1 Mimic Tear \u1EDF Nokron", "Boss", 12020850, "Nokron, Eternal City, \u0111\u01B0\u1EDDng ch\xEDnh t\u1EEB h\u1ED1 sao b\u0103ng", ["\u0110i t\u1EEB h\u1ED1 sao b\u0103ng Limgrave v\xE0o Nokron.", "Qua c\xE1c m\xE1i nh\xE0 \u0111\u1EBFn \u0111\u1EA5u tr\u01B0\u1EDDng Mimic Tear; c\xF3 th\u1EC3 th\xE1o trang b\u1ECB tr\u01B0\u1EDBc khi b\u01B0\u1EDBc qua s\u01B0\u01A1ng r\u1ED3i m\u1EB7c l\u1EA1i.", "H\u1EA1 b\u1EA3n sao v\xE0 ti\u1EBFp t\u1EE5c qua c\xE2y c\u1EA7u l\u1EDBn."]),
  entry("mimic-tear", "ranni-fingerslayer", "Nokron & Ranni", "L\u1EA5y Fingerslayer Blade cho Ranni", "Quest", null, "Nokron, Eternal City, r\u01B0\u01A1ng d\u01B0\u1EDBi Night\u2019s Sacred Ground", ["Sau Radahn, t\xECm h\u1ED1 sao b\u0103ng ph\xEDa nam Mistwood v\xE0 v\xE0o Nokron.", "\u0110i qua Night\u2019s Sacred Ground, m\u1EDF r\u01B0\u01A1ng d\u01B0\u1EDBi t\u01B0\u1EE3ng \u0111\u1EC3 l\u1EA5y Fingerslayer Blade.", "Mang v\u1EADt ph\u1EA9m v\u1EC1 Ranni\u2019s Rise \u0111\u1EC3 m\u1EDF n\u1EEDa sau quest."]),
  entry("ranni-fingerslayer", "regal-ancestor", "Nokron & Ranni", "H\u1EA1 Regal Ancestor Spirit", "Boss", 12090800, "Nokron, Hallowhorn Grounds", ["Trong Nokron, th\u1EAFp \u0111\u1EE7 c\xE1c c\u1ED9t l\u1EEDa \u1EDF khu Ancestral Woods.", "T\u01B0\u01A1ng t\xE1c v\u1EDBi x\xE1c h\u01B0\u01A1u \u1EDF Hallowhorn Grounds.", "H\u1EA1 Regal Ancestor Spirit \u0111\u1EC3 nh\u1EADn Remembrance."]),
  entry("regal-ancestor", "gargoyles", "Nokron & Ranni", "H\u1EA1 Valiant Gargoyles", "Boss", 12020800, "Siofra Aqueduct, ph\xEDa b\u1EAFc Nokron", ["T\u1EEB Ancestral Woods \u0111i v\u1EC1 ph\xEDa b\u1EAFc t\u1EDBi Siofra Aqueduct.", "Chu\u1EA9n b\u1ECB ch\u1ED1ng \u0111\u1ED9c; h\u1EA1 Gargoyle \u0111\u1EA7u tr\u01B0\u1EDBc khi con th\u1EE9 hai g\xE2y \xE1p l\u1EF1c.", "D\xF9ng quan t\xE0i sau \u0111\u1EA5u tr\u01B0\u1EDDng \u0111\u1EC3 t\u1EDBi Deeproot Depths."]),
  entry("radahn", "gael-moonveil", "Caelid \xB7 C\u1EEDa v\xE0o DLC", "D\u1ECDn Gael Tunnel, l\u1EA5y Moonveil", "Boss", 32070800, "Gael Tunnel, ranh gi\u1EDBi Limgrave\u2013Caelid", ["V\xE0o Gael Tunnel t\u1EEB ph\xEDa Caelid ho\u1EB7c l\u1ED1i ph\u1EE5 Limgrave.", "M\u1EDF l\u1ED1i t\u1EAFt, h\u1EA1 Magma Wyrm \u1EDF cu\u1ED1i h\u1EA7m.", "Nh\u1EB7t Moonveil v\xE0 Dragon Heart."]),
  entry("gael-moonveil", "millicent", "Caelid \xB7 C\u1EEDa v\xE0o DLC", "B\u1EAFt \u0111\u1EA7u quest Gowry v\xE0 Millicent", "Quest", null, "Gowry\u2019s Shack v\xE0 Church of the Plague, \u0111\xF4ng Caelid", ["N\xF3i v\u1EDBi Gowry t\u1EA1i t\xFAp l\u1EC1u \u0111\u1EC3 nh\u1EADn y\xEAu c\u1EA7u Unalloyed Gold Needle.", "H\u1EA1 Commander O\u2019Neil \u1EDF Swamp of Aeonia r\u1ED3i mang kim v\u1EC1 Gowry.", "\u0110\u01B0a kim \u0111\xE3 s\u1EEDa cho Millicent t\u1EA1i Church of the Plague; n\xF3i l\u1EA1i sau khi t\u1EA3i l\u1EA1i khu v\u1EF1c."]),
  entry("millicent", "fort-faroth", "Caelid \xB7 C\u1EEDa v\xE0o DLC", "L\u1EA5y n\u1EEDa Dectus ph\u1EA3i \u1EDF Fort Faroth", "V\u1EADt ph\u1EA9m", null, "Fort Faroth, Dragonbarrow", ["\u0110i t\u1EDBi Fort Faroth ph\xEDa \u0111\xF4ng Dragonbarrow.", "Qua b\u1EA7y d\u01A1i, leo thang l\xEAn \u0111\u1EC9nh th\xE1p \u0111\u1EA7u ti\xEAn.", "M\u1EDF r\u01B0\u01A1ng l\u1EA5y Dectus Medallion (Right), gh\xE9p v\u1EDBi n\u1EEDa \u1EDF Fort Haight."]),
  entry("fort-faroth", "altus-entry", "Caelid \xB7 C\u1EEDa v\xE0o DLC", "M\u1EDF \u0111\u01B0\u1EDDng l\xEAn Altus Plateau", "Tuy\u1EBFn \u0111\u01B0\u1EDDng", null, "Grand Lift of Dectus ho\u1EB7c Ruin-Strewn Precipice", ["N\u1EBFu \u0111\xE3 c\xF3 hai n\u1EEDa Dectus, \u0111\u1EBFn Grand Lift of Dectus ph\xEDa b\u1EAFc Liurnia v\xE0 gi\u01A1 huy hi\u1EC7u.", "L\u1ED1i kh\xE1c l\xE0 Ruin-Strewn Precipice, h\u1EA1 Magma Wyrm Makar.", "Ch\u1EA1m \xE2n \u0111i\u1EC3n \u0111\u1EA7u Altus; s\u1EF1 ki\u1EC7n n\xE0y c\xF3 th\u1EC3 k\xEDch ho\u1EA1t Radahn Festival."]),
  entry("altus-entry", "volcano-contracts", "Caelid \xB7 C\u1EEDa v\xE0o DLC", "L\xE0m h\u1EE3p \u0111\u1ED3ng Volcano Manor tr\u01B0\u1EDBc Rykard", "Quest", null, "Volcano Manor, Mt. Gelmir", ["V\xE0o Volcano Manor, n\xF3i v\u1EDBi Tanith v\xE0 nh\u1EADn Drawing-Room Key.", "\u0110\u1ECDc c\xE1c l\xE1 th\u01B0 \xE1m s\xE1t tr\xEAn b\xE0n, ho\xE0n th\xE0nh m\u1EE5c ti\xEAu v\xE0 nh\u1EADn th\u01B0\u1EDFng t\u1EEBng l\u1EA7n.", "Xong c\xE1c h\u1EE3p \u0111\u1ED3ng quan tr\u1ECDng tr\u01B0\u1EDBc khi h\u1EA1 Rykard v\xEC nhi\u1EC1u NPC s\u1EBD r\u1EDDi \u0111i."], "H\u1EA1 Rykard s\u1EDBm c\xF3 th\u1EC3 kh\xF3a ph\u1EA7n th\u01B0\u1EDFng quest c\u1EE7a Volcano Manor."),
  entry("volcano-contracts", "rykard", "Caelid \xB7 C\u1EEDa v\xE0o DLC", "H\u1EA1 Rykard, Lord of Blasphemy", "Boss", 9122, "Volcano Manor, Mt. Gelmir", ["Sau c\xE1c h\u1EE3p \u0111\u1ED3ng c\u1EA7n l\xE0m, t\u1EDBi Audience Pathway.", "Nh\u1EB7t Serpent-Hunter trong \u0111\u1EA5u tr\u01B0\u1EDDng v\xE0 d\xF9ng \u0111\xF2n k\u1EF9 n\u0103ng \u0111\u1EC3 \u0111\xE1nh con r\u1EAFn.", "H\u1EA1 Rykard; ki\u1EC3m tra quest Tanith, Patches v\xE0 Bernahl sau tr\u1EADn."]),
  entry("divine-beast", "leda-quests", "Shadow of the Erdtree", "G\u1EB7p \u0111o\xE0n Leda v\xE0 ghi nh\xE1nh quest", "Quest", null, "C\xE1c Miquella\u2019s Cross \u1EDF Gravesite Plain v\xE0 Scadu Altus", ["N\xF3i v\u1EDBi Leda, Freyja, Hornsent, Ansbach, Thiollier khi g\u1EB7p \u1EDF c\xE1c Site of Grace.", "Ngh\u1EC9 v\xE0 n\xF3i l\u1EA1i sau m\u1ED7i boss l\u1EDBn v\xEC l\u1EDDi tho\u1EA1i v\xE0 v\u1ECB tr\xED c\xF3 th\u1EC3 \u0111\u1ED5i.", "Ghi l\u1EF1a ch\u1ECDn xung \u0111\u1ED9t; nh\xE1nh th\u01B0\u1EDFng kh\xE1c nhau c\xF3 th\u1EC3 c\u1EA7n NG+."], "L\u1EF1a ch\u1ECDn NPC \u1EDF DLC c\xF3 ph\u1EA7n th\u01B0\u1EDFng lo\u1EA1i tr\u1EEB nhau."),
  entry("rellana", "dlc-hippo", "Shadow of the Erdtree", "H\u1EA1 Golden Hippopotamus", "Boss", 21000850, "C\u1ED5ng ch\xEDnh Shadow Keep, Scadu Altus", ["T\u1EEB Scadu Altus v\xE0o c\u1ED5ng ch\xEDnh Shadow Keep.", "H\u1EA1 Golden Hippopotamus \u0111\u1EC3 m\u1EDF s\xE2n trong.", "L\u1EA5y Scadutree Fragment trong khu v\u1EF1c v\xE0 ki\u1EC3m tra c\xE1c ng\xE3 r\u1EBD xu\u1ED1ng Storehouse."]),
  entry("dlc-hippo", "dlc-bayle", "Shadow of the Erdtree", "H\u1EA1 Bayle v\xE0 theo quest Igon", "Boss", 2054390800, "Jagged Peak, \u0111\u01B0\u1EDDng l\xEAn t\u1EEB Dragon\u2019s Pit", ["T\u1EEB Gravesite Plain qua Dragon\u2019s Pit \u0111\u1EBFn Jagged Peak.", "G\u1EB7p v\xE0 n\xF3i v\u1EDBi Igon tr\xEAn \u0111\u01B0\u1EDDng; nh\u1EADn Finger c\u1EE7a Igon n\u1EBFu ti\u1EBFn \u0111\xFAng tuy\u1EBFn.", "H\u1EA1 Bayle \u1EDF \u0111\u1EC9nh v\xE0 ki\u1EC3m tra ph\u1EA7n th\u01B0\u1EDFng Dragon Heart."]),
  entry("dlc-bayle", "dlc-putrescent", "Shadow of the Erdtree", "H\u1EA1 Putrescent Knight, g\u1EB7p St. Trina", "Boss", 22000800, "Stone Coffin Fissure, ph\xEDa nam Cerulean Coast", ["\u0110i xu\u1ED1ng khe n\u1EE9t \u1EDF Cerulean Coast, qua c\xE1c quan t\xE0i \u0111\xE1 t\u1EDBi v\u1EF1c cu\u1ED1i.", "Nh\u1EA3y xu\u1ED1ng \u0111\u1EA5u tr\u01B0\u1EDDng v\xE0 h\u1EA1 Putrescent Knight.", "V\xE0o Garden of Deep Purple \u0111\u1EC3 g\u1EB7p St. Trina; theo d\xF5i quest Thiollier."]),
  entry("dlc-putrescent", "dlc-midra", "Shadow of the Erdtree", "H\u1EA1 Midra \u1EDF Abyssal Woods", "Boss", 28000800, "Midra\u2019s Manse, Abyssal Woods", ["V\xE0o Abyssal Woods qua \u0111\u01B0\u1EDDng h\u1EA7m t\u1EEB Shadow Keep.", "\u0110i b\u1ED9 qua v\xF9ng c\xF3 k\u1EBB \u0111\u1ECBch g\xE2y Madness, t\xECm Midra\u2019s Manse.", "M\u1EDF c\xE1c l\u1ED1i t\u1EAFt trong dinh th\u1EF1 r\u1ED3i h\u1EA1 Midra, Lord of Frenzied Flame."]),
  entry("messmer", "dlc-romina", "Shadow of the Erdtree", "H\u1EA1 Romina t\u1EA1i Church of the Bud", "Boss", 2044450800, "Church of the Bud, Ancient Ruins of Rauh", ["T\u1EEB Shadow Keep \u0111i t\u1EDBi Ancient Ruins of Rauh.", "M\u1EDF l\u1ED1i qua \u0111\u1ED1ng \u0111\u1ED5 n\xE1t t\u1EDBi Church of the Bud.", "H\u1EA1 Romina, Saint of the Bud tr\u01B0\u1EDBc khi \u0111\u1ED1t Sealing Tree."], "Tr\u01B0\u1EDBc khi \u0111\u1ED1t Sealing Tree, ho\xE0n t\u1EA5t c\xE1c cu\u1ED9c g\u1EB7p v\xE0 l\u1EF1a ch\u1ECDn NPC DLC c\xF2n mu\u1ED1n l\xE0m."),
  entry("dlc-romina", "dlc-metyr", "Shadow of the Erdtree", "Ho\xE0n th\xE0nh quest Ymir, h\u1EA1 Metyr", "Boss", 25000800, "Cathedral of Manus Metyr v\xE0 Finger Ruins", ["G\u1EB7p Count Ymir t\u1EA1i Cathedral of Manus Metyr \u1EDF \u0111\xF4ng Scadu Altus.", "L\xE0m theo c\xE1c Ruins Map v\xE0 rung chu\xF4ng t\u1EA1i Finger Ruins.", "V\xE0o t\u1EA7ng d\u01B0\u1EDBi nh\xE0 th\u1EDD, h\u1EA1 Metyr, Mother of Fingers; ki\u1EC3m tra nh\xE1nh Jolan/Ymir."]),
  entry("dlc-final", "godfrey-shade", "K\u1EBFt th\xFAc game g\u1ED1c", "H\u1EA1 Golden Shade Godfrey", "Boss", 11000850, "Erdtree Sanctuary, Leyndell", ["T\u1EEB West Capital Rampart \u0111i theo r\u1EC5 c\xE2y l\u1EDBn v\xE0o Erdtree Sanctuary.", "H\u1EA1 b\xF3ng v\xE0ng c\u1EE7a Godfrey.", "Ra ban c\xF4ng, ti\u1EBFp t\u1EE5c l\xEAn Queen\u2019s Bedchamber v\xE0 Elden Throne."]),
  entry("morgott", "sewers-mohg", "K\u1EBFt th\xFAc game g\u1ED1c", "H\u1EA1 Mohg, the Omen d\u01B0\u1EDBi Leyndell", "Boss", 35000800, "Subterranean Shunning-Grounds, \u0111\xE1y c\u1ED1ng", ["T\xECm gi\u1EBFng v\xE0o c\u1ED1ng \u1EDF khu Royal Capital.", "\u0110i qua Underground Roadside, m\u1EDF c\xE1c \u0111\u01B0\u1EDDng \u1ED1ng v\xE0 l\u1ED1i t\u1EAFt.", "H\u1EA1 Mohg, the Omen \u0111\u1EC3 m\u1EDF l\u1ED1i xu\u1ED1ng Frenzied Flame Proscription."]),
  entry("bolt", "frenzy-route", "K\u1EBFt th\xFAc game g\u1ED1c", "Ghi nh\xE1nh Three Fingers tr\u01B0\u1EDBc ending", "Quest", null, "Frenzied Flame Proscription, d\u01B0\u1EDBi \u0111\u1EA5u tr\u01B0\u1EDDng Mohg the Omen", ["Sau Mohg the Omen, \u0111\xE1nh b\u1EE9c t\u01B0\u1EDDng sau r\u01B0\u01A1ng r\u1ED3i xu\u1ED1ng c\xE1c x\xE0 g\u1ED7.", "G\u1EB7p Hyetta n\u1EBFu theo quest c\u1EE7a c\xF4; \u0111\u1EE9ng tr\u01B0\u1EDBc c\xE1nh c\u1EEDa Three Fingers.", "Ch\u1EC9 m\u1EDF c\u1EEDa khi ch\u1EE7 \u0111\u1ED9ng ch\u1ECDn ho\u1EB7c mu\u1ED1n chu\u1EA9n b\u1ECB nh\xE1nh Frenzied Flame."], "Nh\u1EADn Frenzied Flame s\u1EBD kh\xF3a c\xE1c ending kh\xE1c cho \u0111\u1EBFn khi d\xF9ng Miquella\u2019s Needle."),
  entry("fire-giant", "castle-sol", "K\u1EBFt th\xFAc game g\u1ED1c", "H\u1EA1 Commander Niall, l\u1EA5y medallion tr\xE1i", "Boss", 1051570800, "Castle Sol, t\xE2y b\u1EAFc Mountaintops of the Giants", ["V\xE0o Castle Sol, m\u1EDF l\u1ED1i t\u1EAFt t\u1EDBi Church of the Eclipse.", "H\u1EA1 Commander Niall; c\xF3 th\u1EC3 x\u1EED l\xFD hai l\xEDnh tri\u1EC7u h\u1ED3i tr\u01B0\u1EDBc.", "Leo th\xE1p sau boss, l\u1EA5y Haligtree Secret Medallion (Left)."]),
  entry("castle-sol", "ordina", "K\u1EBFt th\xFAc game g\u1ED1c", "M\u1EDF c\u1ED5ng t\u1EDBi Miquella\u2019s Haligtree", "Tuy\u1EBFn \u0111\u01B0\u1EDDng", null, "Ordina, Liturgical Town, Consecrated Snowfield", ["D\xF9ng hai n\u1EEDa medallion t\u1EA1i Grand Lift of Rold \u0111\u1EC3 v\xE0o Hidden Path to the Haligtree.", "Qua Consecrated Snowfield t\u1EDBi Ordina v\xE0 v\xE0o evergaol trong th\u1ECB tr\u1EA5n.", "Th\u1EAFp b\u1ED1n t\u01B0\u1EE3ng l\u1EEDa \u0111\u1EC3 m\u1EDF c\u1ED5ng d\u1ECBch chuy\u1EC3n t\u1EDBi Haligtree."]),
  entry("ordina", "haligtree-loretta", "K\u1EBFt th\xFAc game g\u1ED1c", "H\u1EA1 Loretta \u1EDF Miquella\u2019s Haligtree", "Boss", 15000850, "Haligtree Town, Miquella\u2019s Haligtree", ["\u0110i t\u1EEB t\xE1n c\xE2y xu\u1ED1ng Haligtree Town, m\u1EDF \u0111\u01B0\u1EDDng t\u1EAFt.", "H\u1EA1 Loretta, Knight of the Haligtree.", "Qua c\u1EA7u t\u1EDBi Elphael, Brace of the Haligtree."]),
  entry("haligtree-loretta", "malenia", "K\u1EBFt th\xFAc game g\u1ED1c", "H\u1EA1 Malenia", "Boss", 9120, "Elphael, cu\u1ED1i khu Haligtree Roots", ["\u0110i qua Elphael, m\u1EDF \xE2n \u0111i\u1EC3n Drainage Channel v\xE0 Haligtree Roots.", "H\u1EA1 Malenia; chu\u1EA9n b\u1ECB ch\u1ED1ng Scarlet Rot v\xE0 h\u1ECDc n\xE9 Waterfowl Dance.", "N\u1EBFu l\xE0m Millicent, ki\u1EC3m tra nh\xE1nh quest/kim t\u1EA1i khu v\u1EF1c sau tr\u1EADn."]),
  entry("malenia", "godskin-duo", "K\u1EBFt th\xFAc game g\u1ED1c", "H\u1EA1 Godskin Duo", "Boss", 13000850, "Dragon Temple, Crumbling Farum Azula", ["T\u1EEB Dragon Temple \u0111i qua c\xE1c ban c\xF4ng \u0111\u1EC3 m\u1EDF l\u1ED1i t\u1EDBi \u0111\u1EA5u tr\u01B0\u1EDDng.", "D\xF9ng c\u1ED9t \u0111\xE1 \u0111\u1EC3 c\u1EAFt t\u1EA7m nh\xECn; Sleep Pots c\xF3 th\u1EC3 t\u1EA1m v\xF4 hi\u1EC7u m\u1ED9t boss.", "H\u1EA1 Godskin Duo r\u1ED3i ti\u1EBFp t\u1EE5c t\u1EDBi Beside the Great Bridge."]),
  entry("godskin-duo", "placidusax", "K\u1EBFt th\xFAc game g\u1ED1c", "H\u1EA1 Dragonlord Placidusax", "Boss", 13000830, "Crumbling Farum Azula, l\u1ED1i n\u1EB1m xu\u1ED1ng \u1EDF v\xE1ch \u0111\xE1", ["T\u1EEB Beside the Great Bridge, quay xu\u1ED1ng khu thang m\xE1y v\xE0 ra m\xE9p v\u1EF1c.", "Nh\u1EA3y theo c\xE1c m\u1EA3nh t\u01B0\u1EDDng xu\u1ED1ng s\xE0n \u0111\xE1, n\u1EB1m t\u1EA1i ch\u1ED7 tr\u1ED1ng \u0111\u1EC3 v\xE0o \u0111\u1EA5u tr\u01B0\u1EDDng.", "H\u1EA1 Dragonlord Placidusax, ki\u1EC3m tra Remembrance."]),
  entry("maliketh", "gideon", "K\u1EBFt th\xFAc game g\u1ED1c", "H\u1EA1 Sir Gideon Ofnir", "Boss", 11050850, "Erdtree Sanctuary, Leyndell Ashen Capital", ["T\u1EEB \xE2n \u0111i\u1EC3n Ashen Capital \u0111i v\xE0o Erdtree Sanctuary.", "H\u1EA1 Sir Gideon Ofnir; quay l\u1EA1i Roundtable Hold ki\u1EC3m tra \u0111\u1ED3 c\xF2n c\u1EA7n mua tr\u01B0\u1EDBc NG+."]),
  entry("gideon", "hoarah-loux", "K\u1EBFt th\xFAc game g\u1ED1c", "H\u1EA1 Godfrey / Hoarah Loux", "Boss", 11050800, "Elden Throne, Leyndell Ashen Capital", ["T\u1EEB Queen\u2019s Bedchamber \u0111i l\xEAn Elden Throne.", "H\u1EA1 Godfrey; \u1EDF pha hai ch\xFA \xFD c\xE1c \u0111\xF2n v\u1EADt v\xE0 s\xF3ng ch\u1EA5n.", "Ch\u1EA1m \xE2n \u0111i\u1EC3n r\u1ED3i chu\u1EA9n b\u1ECB tr\u1EADn Radagon/Elden Beast."])
