  { id: "ending-frenzy", phase: "K\u1EBFt th\xFAc \xB7 Nhi\u1EC1u l\u01B0\u1EE3t ch\u01A1i", title: "Ending Lord of Frenzied Flame", flag: 22, kind: "Ending", actions: ["M\u1EDF tuy\u1EBFn Three Fingers \u1EDF Subterranean Shunning-Grounds.", "Ch\u1ECDn nh\xE1nh Frenzied Flame sau Elden Beast \u1EDF m\u1ED9t l\u01B0\u1EE3t ch\u01A1i ph\xF9 h\u1EE3p.", "N\u1EBFu mu\u1ED1n \u0111\u1ED5i nh\xE1nh sau khi nh\u1EADn Frenzied Flame, c\u1EA7n tuy\u1EBFn Miquella\u2019s Needle."] }
