  step.phase = step.phase.replace(" \xB7 DEMO", "");
  step.mapQuery = step.mapQuery || queries[step.id] || step.title.replace(/^(Hạ|Lấy|Dọn|Gặp|Mở|Bắt đầu|Hoàn thành|Nhặt|Nói với|Quay lại)\s+/u, "");
